src <- .context$bslib_source

# Split source by file header marker and extract filenames and contents
parts <- strsplit(src, '# ---- FILE: ')[[1]]
# The first part may be header preamble; subsequent parts start with filename
files <- list()
if (length(parts) > 1) {
  for (i in 2:length(parts)) {
    part <- parts[[i]]
    # filename is up to first newline
    nl <- regexpr('\n', part, fixed = FALSE)
    fname <- if (nl[1] == -1) part else substr(part, 1, nl[1]-1)
    content <- if (nl[1] == -1) '' else substr(part, nl[1]+1, nchar(part))
    files[[fname]] <- content
  }
}

# Helper to find first snippet containing a fixed substring
find_in_file <- function(content, sub, context=200) {
  pos <- regexpr(sub, content, fixed = TRUE)
  if (pos[1] == -1) return(NULL)
  start <- max(1, pos[1] - context)
  end <- min(nchar(content), pos[1] + nchar(sub) + context)
  substr(content, start, end)
}

# Look for files that mention 'foreground', '_brand', 'brand.yml' (fixed searches)
interesting <- list()
for (fname in names(files)) {
  cont <- files[[fname]]
  if (nchar(cont) == 0) next
  hits <- list()
  for (pat in c('foreground', '_brand', 'brand.yml', 'brand.yaml', 'brand-', 'brand_')) {
    snip <- find_in_file(cont, pat)
    if (!is.null(snip)) hits[[pat]] <- snip
  }
  if (length(hits) > 0) interesting[[fname]] <- hits
}

# Show filenames that mention these patterns
filenames <- names(interesting)

# For a concise view, show up to first 12 files and their snippets
out <- list(
  num_files = length(files),
  num_interesting_files = length(filenames),
  interesting_files = if (length(filenames) > 0) {
    lapply(head(filenames, 12), function(f) list(filename = f, snippets = interesting[[f]]))
  } else character()
)

