get_snippets <- function(fname, pattern, context = 250) {
  content <- files[[fname]]
  if (is.null(content)) return(NULL)
  pos <- gregexpr(pattern, content, ignore.case = TRUE, perl = TRUE)[[1]]
  if (pos[1] == -1) return(NULL)
  sapply(head(pos, 8), function(p) {
    start <- max(1, p - context)
    end <- min(nchar(content), p + nchar(pattern) + context)
    substr(content, start, end)
  })
}

