# Helper to search and return nearby context
search_in_file <- function(fname, pattern, context = 400, fixed = FALSE, ignore.case = TRUE) {
  content <- files[[fname]]
  if (is.null(content)) return(NULL)
  if (fixed) pos <- gregexpr(pattern, content, fixed = TRUE)[[1]] else pos <- gregexpr(pattern, content, ignore.case = ignore.case, perl = TRUE)[[1]]
  if (pos[1] == -1) return(NULL)
  starts <- as.integer(pos)
  # return first few occurrences with context
  lapply(head(starts, 6), function(p) {
    s <- max(1, p - context)
    e <- min(nchar(content), p + context)
    substr(content, s, e)
  })
}

