get_full_scss_function <- function(content, func_name) {
  pos <- regexpr(func_name, content, fixed = TRUE)[1]
  if (pos == -1) return(NULL)
  # find start of the line containing function
  start_line <- max(1, regexpr('\n', substr(content, 1, pos), fixed = TRUE)[1])
  # Heuristic: capture from func_name back 200 chars and forward 1200 chars
  s <- max(1, pos - 200)
  e <- min(nchar(content), pos + 2000)
  substr(content, s, e)
}

