get_fixed_snippet <- function(fname, term, pre = 300, post = 800) {
  content <- files[[fname]]
  if (is.null(content)) return(NULL)
  pos <- regexpr(term, content, fixed = TRUE)[1]
  if (pos == -1) return(NULL)
  start <- max(1, pos - pre)
  end <- min(nchar(content), pos + nchar(term) + post)
  substr(content, start, end)
}

